def segments_from(markers):
    by_u={}
    for r,c in markers:by_u.setdefault(r+c,[]).append((r,c))
    segs=[]
    for u,pts in by_u.items():
        rs=sorted(r for r,c in pts)
        runs=[]
        for r in rs:
            if not runs or r>runs[-1][-1]+1:runs.append([r])
            else:runs[-1].append(r)
        for run in runs:
            vs=[2*r-u for r in run]
            segs.append((u,min(vs),max(vs),run))
    return segs

def pred(markers, loext=0,hiext=0, lop='>=', hip='<='):
    segs=segments_from(markers)
    res=set()
    # bounding grid r,c 0..15
    for u1,l1,h1,runs1 in segs:
      for u2,l2,h2,runs2 in segs:
       if u1>=u2: continue
       lo=max(l1,l2)-loext; hi=min(h1,h2)+hiext
       if lo>hi: continue
       for r in range(16):
        for c in range(16):
         u=r+c; v=r-c
         if u1<u<u2 and ((v>=lo) if lop=='>=' else v>lo) and ((v<=hi) if hip=='<=' else v<hi) and (r,c) not in markers:
          res.add((r,c))
    return res
