def segments_diagonal(markers, orientation='diff'):
    by_d={}
    for r,c in markers:
      d=(c-r) if orientation=='diff' else (c+r)
      s=(r+c) if orientation=='diff' else (c-r)
      by_d.setdefault(d,[]).append((r,c,s))
    segs=[]
    for d, pts in by_d.items():
      # line segment contiguous in row; r changes by1 along diag, can have gaps; split runs
      ps=sorted(pts)
      runs=[]
      for p in ps:
        if not runs or p[0] > runs[-1][-1][0]+1: runs.append([p])
        else:runs[-1].append(p)
      for run in runs:
        ss=[p[2] for p in run]
        segs.append((d,min(ss),max(ss),[p[0] for p in run]))
    return segs

def pred_rule(markers,orient):
    segs=segments_diagonal(markers,orient); res=set()
    for i,(d1,a1,b1,rs1) in enumerate(segs):
      for d2,a2,b2,rs2 in segs[i+1:]:
        if d1==d2:continue
        lo=max(a1,a2); hi=min(b1,b2)
        if lo>hi:continue
        dl,dh=sorted((d1,d2))
        for r in range(16):
          for c in range(16):
            d=(c-r) if orient=='diff' else(c+r)
            s=(r+c) if orient=='diff' else(c-r)
            if dl<d<dh and lo<=s<=hi and (r,c) not in markers:res.add((r,c))
    return res
